// --- GLOBAL HELPER: Formatting Currency ---
        function formatCurrency(num, hideDecimals = true) {
            const currency = document.getElementById('global-currency').value;
            let locale = 'en-US';
            if (currency === 'INR') locale = 'en-IN';
            if (currency === 'GBP') locale = 'en-GB';
            if (currency === 'EUR') locale = 'de-DE';
            if (num === Infinity || num === "∞") return "∞";
            const opts = { style: 'currency', currency: currency };
            if (hideDecimals) { opts.maximumFractionDigits = 0; }
            return num.toLocaleString(locale, opts);
        }
        function formatCompactCurrency(num) {
            const currency = document.getElementById('global-currency').value;
            let prefix = '';
            if (currency === 'USD') prefix = '$';
            if (currency === 'INR') prefix = '₹';
            if (currency === 'GBP') prefix = '£';
            if (currency === 'EUR') prefix = '€';
            if (num >= 1000000) return prefix + (num / 1000000).toFixed(2) + 'M';
            if (num >= 1000) return prefix + (num / 1000).toFixed(0) + 'k';
            return prefix + num.toFixed(0);
        }
        // --- 1. Freemium Compute Death Simulator ---
        function calcFreemiumDeath() {
            const freeUsersMo = parseFloat(document.getElementById('free-users-mo').value) || 0;
            const costPerUser = parseFloat(document.getElementById('free-cost-per-user').value) || 0;
            const conversion = (parseFloat(document.getElementById('free-conversion').value) || 0) / 100;
            const arpu = parseFloat(document.getElementById('free-arpu').value) || 0;
            const reserves = parseFloat(document.getElementById('free-reserves').value) || 0;
            const overhead = parseFloat(document.getElementById('free-overhead').value) || 0;
            const computeAddedMo = freeUsersMo * costPerUser;
            const mrrAddedMo = (freeUsersMo * conversion) * arpu;
            document.getElementById('free-cost-added').textContent = formatCurrency(computeAddedMo, false);
            document.getElementById('free-mrr-added').textContent = formatCurrency(mrrAddedMo, false);
            const diagnosis = document.getElementById('free-diagnosis');
            const netMonthlyChange = mrrAddedMo - computeAddedMo;
            if (netMonthlyChange > 0) {
                diagnosis.textContent = `Model is viable. Every cohort adds ${formatCurrency(netMonthlyChange, false)} in net positive MRR after compute costs.`;
                diagnosis.className = "text-emerald-400 mt-2 block";
            } else {
                const burnAddedPerMonth = Math.abs(netMonthlyChange);
                let cash = reserves;
                let currentBurn = overhead;
                let months = 0;
                while (cash > 0 && months < 120) {
                    months++;
                    currentBurn += burnAddedPerMonth;
                    cash -= currentBurn;
                }
                if (months >= 120) {
                    diagnosis.textContent = `Compute deficit exists but reserves are vast. Bleeding ${formatCurrency(burnAddedPerMonth, false)} extra per month.`;
                    diagnosis.className = "text-amber-400 mt-2 block";
                } else {
                    diagnosis.textContent = `CRITICAL: The compounding compute deficit will bankrupt the company in approximately ${months} months.`;
                    diagnosis.className = "text-red-500 font-bold mt-2 block";
                }
            }
        }
        // --- 2. Co-Founder Equity Engine ---
        function calcEquitySplit() {
            const cashA = parseFloat(document.getElementById('eq-a-cash').value) || 0;
            const timeA = parseFloat(document.getElementById('eq-a-time').value) || 0;
            const cashB = parseFloat(document.getElementById('eq-b-cash').value) || 0;
            const timeB = parseFloat(document.getElementById('eq-b-time').value) || 0;
            const riskA = (cashA * 4) + (timeA * 2);
            const riskB = (cashB * 4) + (timeB * 2);
            const totalRisk = riskA + riskB;
            let pctA = 50;
            let pctB = 50;
            if (totalRisk > 0) {
                pctA = (riskA / totalRisk) * 100;
                pctB = (riskB / totalRisk) * 100;
            }
            const barA = document.getElementById('bar-eq-a');
            const barB = document.getElementById('bar-eq-b');
            barA.style.width = pctA + '%';
            barA.innerText = `Partner A: ${pctA.toFixed(1)}%`;
            barB.style.width = pctB + '%';
            barB.innerText = `Partner B: ${pctB.toFixed(1)}%`;
        }
        // --- 3. Working Capital Death Spiral Engine ---
        function calcGrowthTrap() {
            const upfrontCost = parseFloat(document.getElementById('wcds-upfront-cost').value) || 0;
            const termsDays = parseFloat(document.getElementById('wcds-terms').value) || 30;
            const newDeals = parseFloat(document.getElementById('wcds-deals').value) || 0;
            const monthsDelay = termsDays / 30;
            const monthlyUpfrontDrain = upfrontCost * newDeals;
            const requiredReserve = monthlyUpfrontDrain * monthsDelay;
            const resElement = document.getElementById('wcds-hole-result');
            resElement.textContent = formatCurrency(requiredReserve);
            const diagElement = document.getElementById('wcds-diagnosis');
            if (requiredReserve > 100000) {
                diagElement.textContent = `Critical Treasury Strain: You must float ${formatCurrency(requiredReserve)} before cash hits the bank.`;
                diagElement.className = "font-bold text-sm text-rose-500 mt-2";
            } else if (requiredReserve > 25000) {
                diagElement.textContent = `Moderate Treasury Drain: Growth is causing a ${formatCurrency(requiredReserve)} cash gap. Monitor runway closely.`;
                diagElement.className = "font-bold text-sm text-amber-500 mt-2";
            } else {
                diagElement.textContent = `Healthy Operations: The required float of ${formatCurrency(requiredReserve)} is manageable.`;
                diagElement.className = "font-bold text-sm text-emerald-500 mt-2";
            }
        }
        // --- 4. DAOC Engine (Founder Opportunity Cost) ---
        function calcDAOC() {
            const corpSalary = parseFloat(document.getElementById('daoc-corp-salary').value) || 0;
            const startupSalary = parseFloat(document.getElementById('daoc-startup-salary').value) || 0;
            const years = parseFloat(document.getElementById('daoc-years').value) || 1;
            const marketReturn = (parseFloat(document.getElementById('daoc-market-return').value) || 0) / 100;
            const salaryDeficit = corpSalary - startupSalary;
            let lostWealth = 0;
            for (let i = 1; i <= years; i++) {
                lostWealth += salaryDeficit * Math.pow(1 + marketReturn, years - i + 1);
            }
            const exitTarget = parseFloat(document.getElementById('daoc-exit').value) || 0;
            const equity = (parseFloat(document.getElementById('daoc-equity').value) || 0) / 100;
            const probSuccess = (parseFloat(document.getElementById('daoc-prob').value) || 0) / 100;
            const expectedStartupWealth = exitTarget * equity * probSuccess;
            document.getElementById('daoc-lost-wealth').innerText = formatCompactCurrency(lostWealth);
            document.getElementById('daoc-expected-wealth').innerText = formatCompactCurrency(expectedStartupWealth);
            const verdict = document.getElementById('daoc-verdict');
            if (expectedStartupWealth > lostWealth) {
                verdict.innerText = "The startup is mathematically worth the risk.";
                verdict.className = "text-sm font-bold text-cyan-400 mt-2";
            } else {
                verdict.innerText = "Warning: The opportunity cost exceeds expected risk-adjusted returns.";
                verdict.className = "text-sm font-bold text-rose-500 mt-2";
            }
        }
        // --- 5. Zombie Startup Early Warning System ---
        function calcZombieRisk() {
            const growth = parseFloat(document.getElementById('zombie-growth').value) || 0;
            const runway = parseFloat(document.getElementById('zombie-runway').value) || 0;
            const raiseMonths = parseFloat(document.getElementById('zombie-raise-months').value) || 0;
            let score = 0;
            if (growth < 20) score += 40;
            else if (growth < 40) score += 20;
            if (runway < 10) score += 30;
            else if (runway < 18) score += 10;
            if (raiseMonths > 18) score += 30;
            else if (raiseMonths > 12) score += 15;
            const riskDisplay = document.getElementById('zombie-risk-score');
            const status = document.getElementById('zombie-status');
            riskDisplay.innerText = Math.min(score, 100) + '%';
            if (score >= 70) {
                riskDisplay.className = "font-mono text-4xl font-black text-rose-500";
                status.innerText = "Critical: Default Dead / Zombie Status";
                status.className = "font-bold text-lg text-rose-500";
            } else if (score >= 40) {
                riskDisplay.className = "font-mono text-4xl font-black text-amber-500";
                status.innerText = "Warning: Stagnation Risk Detected";
                status.className = "font-bold text-lg text-amber-500";
            } else {
                riskDisplay.className = "font-mono text-4xl font-black text-emerald-500";
                status.innerText = "Healthy: High Growth / Default Alive";
                status.className = "font-bold text-lg text-emerald-500";
            }
        }
        // --- 6. Runway Logic ---
        function calcRunway() {
            const cash = parseFloat(document.getElementById('cash').value) || 0;
            const burn = parseFloat(document.getElementById('burn').value) || 0;
            const revenue = parseFloat(document.getElementById('revenue').value) || 0;
            const netBurn = burn - revenue;
            let months;
            let dateStr = "Indefinite";
            let colorClass = "text-emerald-500";
            let fuelWidth = '100%';
            if (netBurn <= 0) {
                months = "∞";
                dateStr = "Profitable / Break-even";
                colorClass = "text-emerald-400";
            } else {
                months = (cash / netBurn);
                const today = new Date();
                const futureDate = new Date(today.getFullYear(), today.getMonth(), today.getDate());
                futureDate.setMonth(futureDate.getMonth() + Math.floor(months));
                dateStr = futureDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
                if (months < 6) colorClass = "text-rose-500";
                else if (months < 12) colorClass = "text-amber-500";
                fuelWidth = Math.min((months / 24) * 100, 100) + '%';
            }
            const display = document.getElementById('months-left');
            display.innerText = months === "∞" ? months : months.toFixed(1);
            display.className = `text-6xl font-mono font-bold mb-2 ${colorClass}`;
            document.getElementById('death-date').innerText = "Projected Zero Date: " + dateStr;
            document.getElementById('fuel-bar').style.width = fuelWidth;
            if (months < 6) { document.getElementById('fuel-bar').className = "h-full bg-rose-500 transition-all duration-1000"; }
            else { document.getElementById('fuel-bar').className = "h-full bg-emerald-500 transition-all duration-1000"; }
        }
        // --- 7. SaaS Metrics Engine ---
        function calcSaaSMetrics() {
            const growth = parseFloat(document.getElementById('saas-growth').value) || 0;
            const margin = parseFloat(document.getElementById('saas-margin').value) || 0;
            const r40 = growth + margin;
            const r40Display = document.getElementById('r40-score');
            const r40Status = document.getElementById('r40-status');
            r40Display.innerText = r40 + '%';
            if (r40 >= 40) { r40Display.className = "font-mono text-3xl font-black text-emerald-400"; r40Status.innerText = "Premium Efficiency"; }
            else { r40Display.className = "font-mono text-3xl font-black text-rose-500"; r40Status.innerText = "Underperforming"; }
            const netBurn = parseFloat(document.getElementById('saas-net-burn').value) || 0;
            const netARR = parseFloat(document.getElementById('saas-net-arr').value) || 1;
            const burnMultiple = netBurn / netARR;
            const burnDisplay = document.getElementById('burn-score');
            const burnStatus = document.getElementById('burn-status');
            burnDisplay.innerText = burnMultiple.toFixed(2) + 'x';
            if (burnMultiple <= 1.0) { burnDisplay.className = "font-mono text-3xl font-black text-emerald-400"; burnStatus.innerText = "Elite Level"; }
            else if (burnMultiple <= 1.5) { burnDisplay.className = "font-mono text-3xl font-black text-emerald-500"; burnStatus.innerText = "Great Level"; }
            else if (burnMultiple <= 2.0) { burnDisplay.className = "font-mono text-3xl font-black text-amber-500"; burnStatus.innerText = "Suspect"; }
            else { burnDisplay.className = "font-mono text-3xl font-black text-rose-500"; burnStatus.innerText = "Highly Inefficient"; }
        }
        // --- 8. Cap Table Simulator ---
        let chartInstance = null;
        function initChart() {
            const ctx = document.getElementById('equityChart').getContext('2d');
            chartInstance = new Chart(ctx, {
                type: 'doughnut',
                data: {
                    labels: ['Founders', 'Investors', 'Pool'],
                    datasets: [{
                        data: [60, 20, 20],
                        backgroundColor: ['#a855f7', '#3b82f6', '#10b981'],
                        borderWidth: 0,
                        hoverOffset: 4
                    }]
                },
                options: {
                    responsive: true, maintainAspectRatio: false,
                    plugins: { legend: { display: false } },
                    cutout: '75%'
                }
            });
        }
        function updateChart() {
            let f = parseInt(document.getElementById('founder-split').value);
            let i = parseInt(document.getElementById('investor-split').value);
            if (f + i > 100) { i = 100 - f; document.getElementById('investor-split').value = i; }
            let p = 100 - f - i;
            document.getElementById('founder-val').innerText = f + '%';
            document.getElementById('investor-val').innerText = i + '%';
            document.getElementById('pool-val').innerText = p + '%';
            if (chartInstance) {
                chartInstance.data.datasets[0].data = [f, i, p];
                chartInstance.update();
            }
            calcExitWaterfall();
        }
        // --- 9. Exit Waterfall ---
        function calcExitWaterfall() {
            const preMoney = parseFloat(document.getElementById('exit-pre-money').value) || 0;
            const invest = parseFloat(document.getElementById('exit-investment').value) || 0;
            const exitVal = parseFloat(document.getElementById('exit-value').value) || 0;
            const founderPct = parseInt(document.getElementById('founder-split').value) / 100 || 0;
            const postMoney = preMoney + invest;
            let investorPct = 0;
            if (postMoney > 0) investorPct = invest / postMoney;
            const founderPayout = exitVal * founderPct;
            document.getElementById('res-post-money').innerText = formatCompactCurrency(postMoney);
            document.getElementById('res-investor-pct').innerText = (investorPct * 100).toFixed(1) + '%';
            document.getElementById('res-founder-payout').innerText = formatCompactCurrency(founderPayout);
        }
        // --- 10. Unit Economics & Payback ---
        function calcUnitEconomics() {
            const spend = parseFloat(document.getElementById('marketing-spend').value) || 0;
            const customers = parseFloat(document.getElementById('new-customers').value) || 1;
            const arpu = parseFloat(document.getElementById('arpu').value) || 0;
            const churn = parseFloat(document.getElementById('churn-rate').value) || 0.1;
            const grossMargin = (parseFloat(document.getElementById('gross-margin').value) || 100) / 100;
            const cac = spend / customers;
            const ltv = arpu / (churn / 100) * grossMargin;
            const ratio = cac > 0 ? (ltv / cac) : 0;
            const marginRev = arpu * grossMargin;
            const payback = marginRev > 0 ? (cac / marginRev) : 0;
            document.getElementById('cac-result').innerText = formatCurrency(cac, false);
            document.getElementById('ltv-result').innerText = formatCurrency(ltv, false);
            const ratioEl = document.getElementById('ratio-result');
            ratioEl.innerText = ratio.toFixed(1) + 'x';
            if (ratio < 1) ratioEl.className = "text-lg font-mono font-bold text-rose-500";
            else if (ratio < 3) ratioEl.className = "text-lg font-mono font-bold text-amber-500";
            else ratioEl.className = "text-lg font-mono font-bold text-emerald-500";
            document.getElementById('payback-result').innerText = payback.toFixed(1) + ' Mo';
        }
        // --- 11. Idea Validator Logic ---
        function checkScore() {
            const checks = document.querySelectorAll('.validator-check:checked');
            const score = checks.length;
            const display = document.getElementById('viability-score');
            display.innerText = score + "/4";
            if (score === 4) display.className = "text-3xl font-mono font-black text-emerald-500";
            else if (score === 3) display.className = "text-3xl font-mono font-black text-amber-500";
            else display.className = "text-3xl font-mono font-black text-slate-500";
        }
        // --- 12. Dynamic Contract Generator (Founder vs Partner) ---
        function addPartyBlock(role = '', name = '', isRemovable = true) {
            const container = document.getElementById('contract-parties-blocks');
            const blockId = 'party-' + Date.now() + Math.floor(Math.random() * 1000);
            const removeBtn = isRemovable ? `<button onclick="document.getElementById('${blockId}').remove()" class="absolute top-1 right-1 text-slate-500 hover:text-rose-500 text-xs font-bold transition p-1 rounded opacity-0 group-hover:opacity-100"><svg class="w-4 h-4 inline-block text-rose-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg></button>` : '';
            const blockHTML = `
                <div class="relative party-block group bg-slate-800 p-3 rounded border border-slate-700 shadow-sm" id="${blockId}">
                    ${removeBtn}
                    <input type="text" placeholder="Role (e.g., Co-Founder)" class="w-full text-xs font-bold mb-1 outline-none text-slate-400 uppercase tracking-wider party-role bg-transparent" value="${role}">
                    <input type="text" placeholder="Name" class="w-full text-sm outline-none text-white font-medium party-name border-b border-dashed border-slate-600 focus:border-emerald-500 bg-transparent" value="${name}">
                </div>
            `;
            container.insertAdjacentHTML('beforeend', blockHTML);
        }
        function addContractBlock(title = '', content = '') {
            const container = document.getElementById('contract-dynamic-blocks');
            const blockId = 'block-' + Date.now() + Math.floor(Math.random() * 1000);
            const blockHTML = `
                <div class="bg-slate-800 p-4 rounded-xl border border-slate-700 relative contract-block shadow-sm group" id="${blockId}">
                    <button onclick="document.getElementById('${blockId}').remove()" class="absolute top-2 right-2 text-slate-500 hover:text-rose-500 text-xs font-bold transition p-1 bg-slate-900 rounded opacity-0 group-hover:opacity-100">Delete Block</button>
                    <input type="text" placeholder="Clause Title (e.g., INTELLECTUAL PROPERTY)" class="w-full font-bold mb-2 p-2 border-b border-slate-700 outline-none text-white bg-transparent block-title" value="${title}">
                    <textarea placeholder="Clause details..." class="w-full h-24 p-2 text-sm text-slate-300 bg-slate-900 rounded border border-slate-700 outline-none resize-none block-content leading-relaxed">${content}</textarea>
                </div>
            `;
            container.insertAdjacentHTML('beforeend', blockHTML);
        }
        function switchContractType() {
            const type = document.getElementById('contract-type').value;
            const partiesContainer = document.getElementById('contract-parties-blocks');
            const clausesContainer = document.getElementById('contract-dynamic-blocks');
            const titleLabel = document.getElementById('parties-title');
            partiesContainer.innerHTML = '';
            clausesContainer.innerHTML = '';
            if (type === 'founder') {
                titleLabel.innerText = "Founders Involved";
                addPartyBlock('Founder 1 (CEO)', '', false);
                addPartyBlock('Founder 2 (CTO)', '', true);
                addContractBlock('1. ROLES & RESPONSIBILITIES', 'Each founder agrees to dedicate full-time effort to the Company. Specific roles will be determined by the Board of Directors.');
                addContractBlock('2. EQUITY VESTING', 'Shares shall be subject to a standard vesting schedule: 25% vesting upon the 1-year anniversary of the Vesting Commencement Date (the "Cliff"), and the remaining 75% vesting in equal monthly installments over the following 36 months.');
                addContractBlock('3. INTELLECTUAL PROPERTY ASSIGNMENT', 'Each Founder assigns to the Company all intellectual property rights related to the Company’s business that the Founder develops during their tenure.');
                addContractBlock('4. ACCELERATION ON CHANGE OF CONTROL', 'In the event of a Change of Control, 100% of unvested shares shall immediately vest (Single-Trigger Acceleration).');
            } else {
                titleLabel.innerText = "Partners Involved";
                addPartyBlock('Partner A', '', false);
                addPartyBlock('Partner B', '', true);
                addContractBlock('1. PARTNERSHIP PURPOSE', 'The Partners agree to join together to form a business entity for the purpose of operating the Company and developing its core technology and services.');
                addContractBlock('2. EQUITY & PROFIT SHARING', 'Equity and profits shall be distributed according to the mathematical risk assessment models previously agreed upon.');
                addContractBlock('3. INTELLECTUAL PROPERTY', 'All Partners assign to the Company all intellectual property rights related to the Company’s business developed during their tenure.');
                addContractBlock('4. DECISION MAKING', 'Day-to-day decisions shall be managed by the Managing Partner. Major financial decisions require a majority vote based on equity ownership.');
            }
        }
        async function generateSecureContract() {
            const type = document.getElementById('contract-type').value;
            const company = document.getElementById('contract-company').value || '[Company Name]';
            const date = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
            let contractString = "";
            if (type === 'founder') {
                contractString = `FOUNDER RESTRICTED STOCK AGREEMENT\n\nThis Agreement is entered into on ${date}, by and between ${company} (the "Company") and the undersigned founders.\n\n`;
            } else {
                contractString = `GENERAL PARTNERSHIP AGREEMENT\n\nThis Agreement is entered into on ${date}, for the formation and operation of ${company} (the "Company").\n\n`;
            }
            const parties = document.querySelectorAll('.party-block');
            let signatureSection = `Signatures:\n\n`;
            contractString += `PARTIES INVOLVED:\n`;
            parties.forEach((party) => {
                const role = party.querySelector('.party-role').value.trim() || 'Party';
                const name = party.querySelector('.party-name').value.trim() || '[Unspecified Name]';
                contractString += `- ${name}, ${role}\n`;
                signatureSection += `___________________________\n${name} (${role})\nDate: _________________\n\n`;
            });
            contractString += `\n`;
            const blocks = document.querySelectorAll('.contract-block');
            blocks.forEach((block) => {
                const title = block.querySelector('.block-title').value.trim();
                const content = block.querySelector('.block-content').value.trim();
                if (title || content) {
                    contractString += `${title}\n${content}\n\n`;
                }
            });
            contractString += signatureSection;
            const outputArea = document.getElementById('contract-output-area');
            document.getElementById('contract-text').textContent = contractString;
            outputArea.classList.remove('hidden');
            const encoder = new TextEncoder();
            const data = encoder.encode(contractString);
            try {
                const hashBuffer = await crypto.subtle.digest('SHA-256', data);
                const hashArray = Array.from(new Uint8Array(hashBuffer));
                const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
                document.getElementById('contract-hash').textContent = hashHex;
                window.currentContractHash = hashHex;
            } catch (err) {
                document.getElementById('contract-hash').textContent = "Crypto API req. HTTPS.";
            }
        }
        function downloadContractPDF() {
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();
            const type = document.getElementById('contract-type').value;
            const content = document.getElementById('contract-text').textContent;
            const hash = window.currentContractHash || "Hash unavailable";
            const includeHash = document.getElementById('pdf-include-hash').checked;
            doc.setFontSize(10);
            const splitText = doc.splitTextToSize(content, 180);
            let yPosition = 20;
            const pageHeight = doc.internal.pageSize.height;
            for (let i = 0; i < splitText.length; i++) {
                if (yPosition > pageHeight - 30) {
                    doc.addPage();
                    yPosition = 20;
                }
                doc.text(splitText[i], 15, yPosition);
                yPosition += 5;
            }
            doc.setFont("helvetica", "normal");
            doc.setFontSize(8);
            doc.setTextColor(150);
            doc.text("Generated securely via ToolkitGen.com | Startup OS", 15, pageHeight - 10);
            if (includeHash) {
                doc.setFont("courier", "bold");
                doc.setTextColor(100);
                doc.text(`Document SHA-256 Hash: ${hash}`, 15, pageHeight - 15);
            }
            const fileName = type === 'founder' ? "Founder_Agreement.pdf" : "Partnership_Agreement.pdf";
            doc.save(fileName);
        }
        // --- Master Recalculation ---
        function calculateAllTools() {
            calcFreemiumDeath();
            calcEquitySplit();
            calcGrowthTrap();
            calcDAOC();
            calcZombieRisk();
            calcRunway();
            calcSaaSMetrics();
            calcExitWaterfall();
            calcUnitEconomics();
        }
        // --- Initialization ---
        document.addEventListener('DOMContentLoaded', () => {
            document.getElementById('global-currency').addEventListener('change', calculateAllTools);
            ['free-users-mo', 'free-cost-per-user', 'free-conversion', 'free-arpu', 'free-reserves', 'free-overhead'].forEach(id => document.getElementById(id).addEventListener('input', calcFreemiumDeath));
            ['eq-a-cash', 'eq-a-time', 'eq-b-cash', 'eq-b-time'].forEach(id => document.getElementById(id).addEventListener('input', calcEquitySplit));
            ['wcds-upfront-cost', 'wcds-tcv', 'wcds-terms', 'wcds-deals'].forEach(id => document.getElementById(id).addEventListener('input', calcGrowthTrap));
            ['daoc-corp-salary', 'daoc-startup-salary', 'daoc-years', 'daoc-market-return', 'daoc-exit', 'daoc-equity', 'daoc-prob'].forEach(id => document.getElementById(id).addEventListener('input', calcDAOC));
            ['zombie-growth', 'zombie-runway', 'zombie-raise-months'].forEach(id => document.getElementById(id).addEventListener('input', calcZombieRisk));
            ['cash', 'burn', 'revenue'].forEach(id => document.getElementById(id).addEventListener('input', calcRunway));
            ['saas-growth', 'saas-margin', 'saas-net-burn', 'saas-net-arr'].forEach(id => document.getElementById(id).addEventListener('input', calcSaaSMetrics));
            initChart();
            document.getElementById('founder-split').addEventListener('input', updateChart);
            document.getElementById('investor-split').addEventListener('input', updateChart);
